private theorem recoveryTerm_sum (hW : WeilPositiveFull lam) (T ℓ t : ℝ) :
    (∑' n : ℕ, recoveryTerm hW T ℓ n t) =
      quantizationCenteredGaussianIntegrand hW T ℓ ((3 / 2 : ℂ) + t * I)

